<?php
declare(strict_types=1);
$clients=is_array($clients??null)?$clients:[];
$profiles=is_array($profiles??null)?$profiles:[];
$items=is_array($items??null)?$items:[];
$error=is_string($error??null)?$error:'';
$notice=is_string($notice??null)?$notice:'';
$csrf=is_string($csrf??null)?$csrf:'';
$brandName=is_string($brandName??null)?$brandName:'Talyvane';
$money=static fn(mixed $minor,mixed $precision):string=>number_format(((int)$minor)/(10**max(0,min(4,(int)$precision))),max(0,min(4,(int)$precision)),'.',',');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Booking quotes · <?= $escape($brandName) ?></title>
<style>
:root{color-scheme:light;--ink:#182638;--muted:#667487;--paper:#f4f2ed;--line:#e6e2d9;--panel:#fffefa;--navy:#142235;--gold:#bd9560}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.6 system-ui,sans-serif}.shell{width:min(1120px,calc(100% - 36px));margin:auto}.top{padding:22px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.top a{color:var(--ink)}h1{font:400 clamp(34px,5vw,52px) Georgia,serif;margin:42px 0 10px}.intro{color:var(--muted);max-width:760px}.panel{background:var(--panel);border:1px solid var(--line);padding:24px;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.field{display:grid;gap:6px}.field label{font-size:11px;font-weight:700}.field input,.field select{width:100%;padding:11px;border:1px solid var(--line);background:white;font:inherit}.button{border:0;background:var(--navy);color:white;padding:12px 16px;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;margin-top:16px}.notice,.error{padding:12px 15px;margin:18px 0}.notice{background:#f0f5ef;border:1px solid #d6e2d3;color:#345b39}.error{background:#fff4f2;border:1px solid #e9c9c4;color:#8b3535}.table{width:100%;border-collapse:collapse;background:var(--panel);margin:24px 0 70px}.table th,.table td{padding:12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.table th{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.small{font-size:12px;color:var(--muted)}@media(max-width:650px){.table{display:block;overflow-x:auto}}
</style></head><body><header class="shell top"><strong><?= $escape($brandName) ?> · Booking operations</strong><a href="/admin">Control room</a></header><main class="shell"><h1>Immutable booking quotes.</h1><p class="intro">Issue a quote for one verified client and one published companion profile. The quoted amount, currency, fee breakdown and booking-policy version are snapshotted; acceptance is recorded by the client and the quote can fund only one booking.</p>
<?php if($error!==''):?><div class="error" role="alert"><?= $escape($error) ?></div><?php endif;?><?php if($notice!==''):?><div class="notice" role="status"><?= $escape($notice) ?></div><?php endif;?>
<section class="panel"><h2>Issue a quote</h2><form method="post" action="/admin/booking-quotes"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="grid">
<div class="field"><label for="client_id">Verified client</label><select id="client_id" name="client_id" required><option value="">Select client</option><?php foreach($clients as $client):?><option value="<?= $escape($client['id']) ?>"><?= $escape($client['email']) ?></option><?php endforeach;?></select></div>
<div class="field"><label for="profile_id">Companion profile</label><select id="profile_id" name="profile_id" required><option value="">Select profile</option><?php foreach($profiles as $profile):?><option value="<?= $escape($profile['id']) ?>"><?= $escape($profile['display_name']) ?> · <?= $escape($profile['destination_name']) ?> (<?= $escape($profile['country_code']) ?>)</option><?php endforeach;?></select></div>
<div class="field"><label for="amount">Total amount (major currency units)</label><input id="amount" name="amount" inputmode="decimal" pattern="(?:0|[1-9][0-9]{0,13})(?:\.[0-9]{1,4})?" required placeholder="250.00"></div>
<div class="field"><label for="currency">ISO 4217 currency</label><input id="currency" name="currency" maxlength="3" pattern="[A-Za-z]{3}" required placeholder="GBP"></div>
<div class="field"><label for="expires_at">Expiry (UTC)</label><input id="expires_at" name="expires_at" type="datetime-local" required></div>
</div><p class="small">Tax is not calculated by this workflow. Do not issue a tax-inclusive quote unless the applicable tax treatment has been independently reviewed and configured.</p><button class="button" type="submit">Issue immutable quote</button></form></section>
<section><h2>Quote register</h2><?php if($items===[]):?><p class="small">No quotes have been issued.</p><?php else:?><table class="table"><thead><tr><th>Reference</th><th>Client</th><th>Profile / market</th><th>Amount</th><th>Expiry</th><th>Status</th><th>Policy</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= $escape($item['quote_reference']) ?></td><td><?= $escape($item['client_email']) ?></td><td><?= $escape($item['profile_name']) ?><br><span class="small"><?= $escape($item['country_code']) ?></span></td><td><?= $escape($item['original_currency']) ?> <?= $money($item['original_amount_minor'],$item['currency_precision']) ?></td><td><?= $escape($item['expires_at']) ?> UTC</td><td><?= $item['consumed_at']!==null?'Consumed':($item['accepted_at']!==null?'Accepted':'Awaiting client') ?></td><td><?= $escape($item['policy_version']) ?></td></tr><?php endforeach;?></tbody></table><?php endif;?></section></main></body></html>
